def prod2sum(a, b, c, d):
    sum1 = a**2 + b**2
    sum2 = c**2 + d**2
    n = sum1 * sum2

    def is_square(x):
        s = int(x**0.5)
        return s * s == x

    pairs = []
    for e in range(int(n**0.5) + 1):
        f_squared = n - e**2
        if is_square(f_squared):
            f = int(f_squared**0.5)
            if e <= f:
                pairs.append([e, f])

    return pairs

